// convertPlaceholders converts SQLite-style ? placeholders to PostgreSQL-style $1, $2, etc.
// when running on PostgreSQL
func (t *FAAllocation) convertPlaceholders(sql string, count int) string {
	if t.dbType != database.DBTypePostgres {
		return sql
	}
	result := sql
	for i := 1; i <= count; i++ {
		result = strings.Replace(result, "?", fmt.Sprintf("$%d", i), 1)
	}
	return result
}

// Get retrieves a record from the database by primary key (interface{} for generic API)
// For single primary key: pass the value directly (string, int, etc.)
// For composite keys: pass a map[string]interface{} with field names as keys
func (t *FAAllocation) Get(primaryKey interface{}) bool {
	// A composite primary key (map[string]interface{}, values also as text)
	if pkMap, ok := primaryKey.(map[string]interface{}); ok {
		key := fAAllocationFields.KeyFromMap(pkMap)
		return t.GetByPK(key[0].(types.Code), key[1].(int), FAAllocationAllocation_type(key[2].(int)))
	}

	fmt.Printf("Error: Invalid primary key type for FA_Allocation.Get: %T (use map for composite keys)\n", primaryKey)
	return false
}

// GetByPK retrieves a record by its typed primary key(s) - for direct typed access
func (t *FAAllocation) GetByPK(code types.Code, line_no int, allocation_type FAAllocationAllocation_type) bool {
	// Collect arguments for query
	args := []interface{}{
		code,
		line_no,
		allocation_type,
	}
	return t.rec().Get(args)
}

// Insert inserts the record into the database
func (t *FAAllocation) Insert(runTrigger bool) bool {
	// OnInsert trigger of the business logic, then the field checks of the definition
	t.triggerErr = nil
	if runTrigger {
		if err := t.runOnInsert(); err != nil {
			fmt.Printf("Error: OnInsert trigger failed: %v\n", err)
			t.triggerErr = err
			return false
		}
	}

	// A taken key inserts nothing (ON CONFLICT … DO NOTHING) instead of failing: on PostgreSQL
	// a failed INSERT would abort the transaction
	switch t.rec().Insert() {
	case tables.InsertFailed:
		return false
	case tables.KeyTaken:
		// INSERT fails in the classic way: "<Table> <key> already exists"
		_, key := t.recordKey()
		t.triggerErr = apperrors.TableRecordExists(FAAllocationTableName, key)
		return false
	}
	// The record as written: its xRec from now on (a following Modify or Rename compares with it)
	t.StoreOldValues()
	return true
}

// InsertAll inserts records in bulk (demo data, imports): multi-row INSERT statements, one
// round trip per batch instead of one per record. With runTrigger every record's OnInsert
// trigger runs first, as Insert(true) would; the first failure stops before anything is
// written. Records are written with the receiver's database and company. Errors are
// *tables.BatchInsertError (Index = the record in records). Use it in a transaction: a
// failed batch leaves the earlier batches written.
func (t *FAAllocation) InsertAll(records []*FAAllocation, runTrigger bool) error {
	rows := make([][]interface{}, 0, len(records))
	for i, r := range records {
		r.triggerErr = nil
		if runTrigger {
			if err := r.runOnInsert(); err != nil {
				r.triggerErr = err
				return &tables.BatchInsertError{Index: i, Trigger: true, Err: err}
			}
		}
		rows = append(rows, fAAllocationFields.RowValues(r.fieldRef))
	}
	tableName := fmt.Sprintf("%s$%s", t.company, FAAllocationTableName)
	return tables.InsertRows(t.exec(), t.dbType, tableName, fAAllocationFields.Columns(), rows)
}

// Modify updates the record in the database
func (t *FAAllocation) Modify(runTrigger bool) bool {
	// OnModify trigger of the business logic, then the field checks of the definition
	t.triggerErr = nil
	if runTrigger {
		if err := t.runOnModify(); err != nil {
			fmt.Printf("Error: OnModify trigger failed: %v\n", err)
			t.triggerErr = err
			return false
		}
	}
	// A changed primary key is a rename: run the OnRename trigger
	// before it is written; xRec values are available through OldValue
	keyChanged := fAAllocationFields.KeyChanged(t.fieldRef, t.oldValues)
	if runTrigger && keyChanged {
		if err := t.runOnRename(); err != nil {
			fmt.Printf("Error: OnRename trigger failed: %v\n", err)
			t.triggerErr = err
			return false
		}
	}

	switch t.rec().Modify(t.oldValues) {
	case tables.ModifyFailed:
		return false
	case tables.NothingToSave:
		return true
	}
	// The stored record now matches the current values (including a renamed key)
	if t.oldValues != nil {
		t.StoreOldValues()
	}
	return true
}

// hasFieldChanged checks if a field value has changed from oldValues
func (t *FAAllocation) hasFieldChanged(fieldName string) bool {
	return fAAllocationFields.Changed(t.fieldRef, t.oldValues, fieldName)
}

// SetDB changes the database executor of the record without touching its values — e.g. to
// run a Modify (with its rename cascade) inside a transaction.
func (t *FAAllocation) SetDB(db database.Executor) {
	t.db = db
}

// Delete removes the record from the database
func (t *FAAllocation) Delete(runTrigger bool) bool {
	// OnDelete trigger of the business logic
	t.triggerErr = nil
	if runTrigger {
		if err := t.runOnDelete(); err != nil {
			fmt.Printf("Error: OnDelete trigger failed: %v\n", err)
			t.triggerErr = err
			return false
		}
	}

	return t.rec().Delete()
}

// ========================================
// FlowField Calculations
// ========================================

// CalcFields calculates FlowField values
// Usage:
//
//	customer.CalcFields("balance", "balance_lcy") - Calculate specific fields
//	customer.CalcFields() - Calculate all FlowFields
func (t *FAAllocation) CalcFields(fieldNames ...string) {
	// If no field names specified, calculate all FlowFields
	if len(fieldNames) == 0 {
		t.calcFlowField_account_name()
		return
	}

	// Calculate only specified fields
	for _, fieldName := range fieldNames {
		switch fieldName {
		case "account_name":
			t.calcFlowField_account_name()
		}
	}
}

// calcFlowField_account_name calculates the account_name FlowField
// CalcFormula: Lookup(GLAccount.name)
func (t *FAAllocation) calcFlowField_account_name() {
	t.Account_name = t.calcLookup_account_name()
}

// CalcFieldsForRecords calculates FlowFields for many records at once (list pages):
// one grouped query per FlowField instead of one query per record. records are
// ToMap() results; each gets its FlowField values under the field name. With no
// field names, all FlowFields are calculated.
func (t *FAAllocation) CalcFieldsForRecords(records []map[string]interface{}, fieldNames ...string) {
	if len(records) == 0 {
		return
	}
	if len(fieldNames) == 0 {
		fieldNames = t.GetFlowFields()
	}
	for _, fieldName := range fieldNames {
		switch fieldName {
		case "account_name":
			t.calcForRecords_account_name(records)
		}
	}
}

// calcForRecords_account_name calculates the account_name FlowField for a set of records
// CalcFormula: Lookup(GLAccount.name)
func (t *FAAllocation) calcForRecords_account_name(records []map[string]interface{}) {
	// No single key field to group by: calculate per record, with this record's FlowFilters
	for _, rec := range records {
		r := &FAAllocation{db: t.db, company: t.company, dbType: t.dbType}
		r.FromMap(rec)
		r.calcFlowField_account_name()
		rec["account_name"] = r.Account_name
	}
}

// Helper methods for FlowField calculations

// calcLookup_account_name reads GLAccount.name of the first record matching the
// flow filters (CalcFormula Lookup); blank when there is none
func (t *FAAllocation) calcLookup_account_name() types.Text {
	tableName := fmt.Sprintf("%s$%s", t.company, GLAccountTableName)
	var whereClauses []string
	var args []interface{}
	whereClauses = append(whereClauses, "no = ?")
	args = append(args, t.Account_no)
	whereClause := "1=1"
	if len(whereClauses) > 0 {
		whereClause = strings.Join(whereClauses, " AND ")
	}
	query := t.convertPlaceholders(fmt.Sprintf(`SELECT name FROM "%s" WHERE %s LIMIT 1`, tableName, whereClause), len(args))
	var value sql.NullString
	if err := t.db.QueryRow(query, args...).Scan(&value); err != nil && err != sql.ErrNoRows {
		fmt.Printf("Error: Failed to look up account_name: %v\n", err)
	}
	return types.NewText(value.String)
}

